    double d, theta, a, b, s, w, x, y, z, norm;

    *interpolated_q_bi = (adcs_quat_t){1, 0, 0, 0};

    if ((q0_bi == NULL) || (q1_bi == NULL) || (interpolated_q_bi == NULL))
        return ADCS_E_NULL;

    if (adcs_quat_normalize(q0_bi, &n0) != ADCS_OK)
        return ADCS_E_DEGENERATE;
    if (adcs_quat_normalize(q1_bi, &n1) != ADCS_OK)
        return ADCS_E_DEGENERATE;

    if ((!isfinite(fraction)) || (fraction < 0.0) || (fraction > 1.0))
        return ADCS_E_RANGE;

    d = n0.w * n1.w + n0.x * n1.x + n0.y * n1.y + n0.z * n1.z;
    if (d < 0.0) {
        n1.w = -n1.w;
        n1.x = -n1.x;
        n1.y = -n1.y;
        n1.z = -n1.z;
        d = -d;
    }

    if (d > 0.9995) {
        a = 1.0 - fraction;
        b = fraction;
    } else {
        double dc = ADCS_CLAMP(d, -1.0, 1.0);
        theta = acos(dc);
        s = sin(theta);
        a = sin((1.0 - fraction) * theta) / s;
        b = sin(fraction * theta) / s;
    }

    w = a * n0.w + b * n1.w;
    x = a * n0.x + b * n1.x;
    y = a * n0.y + b * n1.y;
    z = a * n0.z + b * n1.z;

    norm = sqrt(w * w + x * x + y * y + z * z);
    if ((!isfinite(norm)) || (norm <= ADCS_EPS_QUAT)) {
        *interpolated_q_bi = (adcs_quat_t){1, 0, 0, 0};
        return ADCS_E_DEGENERATE;
    }

    result.w = w / norm;
    result.x = x / norm;
    result.y = y / norm;
    result.z = z / norm;
    *interpolated_q_bi = result;
    return ADCS_OK;
}

